# రామాయణం (ఉపవాచకం) – Telugu_01T.pdf పేజీలు 50–52 (Mini Action Plan 2026-27, 22 మార్కులు)
# notes-10.js లో ఉపవాచకం పాఠం లేదు → LESSONS ద్వారా పేరు (build_ssc → window.RAAY_SSC_LN)
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
from qbh import Bank
LESSONS = [{'id': 'tram', 'no': 13, 't': 'రామాయణం (ఉపవాచకం)'}]
B = Bank(13, 'tram'); q = B.q
KQ = 'కింది సంఘటనలు ఏ కాండకు చెందినవో గుర్తించి, వాక్య రూపంలో రాయండి.\n'
KANDA = ['బాలకాండ', 'అయోధ్యకాండ', 'అరణ్యకాండ', 'కిష్కింధకాండ', 'సుందరకాండ', 'యుద్ధకాండ']
L = 'అఆఇఈ'
SETS = [
    [('ఒకనాటి అర్ధరాత్రి మాయావి కిష్కింధకు వచ్చి వాలిని యుద్ధానికి ఆహ్వానించాడు.', 3), ('రామకథ వాల్మీకి మనసులో నాటుకుపోయింది.', 0),
     ('ప్రాణత్యాగానికి సిద్ధపడ్డ సీతకు శుభశకునాలు తోచాయి.', 4), ('దండకారణ్యంలో మునుల ఆశ్రమాలను సందర్శిస్తూ పోతున్నారు సీతారామలక్ష్మణులు.', 2)],
    [('రాముడు తనకు రాజ్యమైనా వనవాసమైనా సమానమేనని ప్రకటించాడు.', 1), ('దగ్గరగా వస్తున్న మారుతిని చూసి రావణుడిగా అనుమానించింది సీత.', 4),
     ('తాటకను వధించమని రాముడితో విశ్వామిత్రుడు అన్నాడు.', 0), ('విభీషణుడు పల్లకీలో సీతాదేవిని శ్రీరాముడి దగ్గరకు చేర్చాడు.', 5)],
    [('భరతుడు రాముని పాదుకలను తీసుకొని నందిగ్రామం చేరాడు.', 1), ('విశ్వామిత్రుడు రామలక్ష్మణులకు బల, అతిబల అనే మంత్రాలను ఉపదేశించాడు.', 0),
     ('శ్రీరాముడు యుద్ధరంగంలో బ్రహ్మాస్త్రంతో రావణుని సంహరించాడు.', 5), ('లంకను కాల్చిన హనుమంతుడు సముద్రంలో తోకను చల్లార్చుకున్నాడు.', 4)],
    [('హనుమంతుడు తాను శ్రీరామదూతనని చెప్పుకొన్నాడు.', 4), ('సుషేణుని చేతిలో విద్యున్మాలి మరణించాడు.', 5),
     ('అయోధ్యలో ఎలా మసలుకోవాలో సీతకు తెలిపాడు.', 1), ('వాలితో వైరమెందుకు వచ్చిందో తెలపమన్నాడు సుగ్రీవుణ్ణి.', 3)],
    [('పంచవటికి ప్రయాణమయ్యారు సీతారామలక్ష్మణులు.', 2), ('దశరథునికి మాటరావడం లేదు కన్నీళ్ళు తప్ప.', 1),
     ('మాయావి ఒక పెద్ద భూగృహంలోకి వెళ్ళాడు.', 3), ('దశరథుడు సపరివారంగా అయోధ్యకు చేరుకున్నాడు.', 0)],
    [('జటాయువు రావణుని ఎదిరించాడు.', 2), ('ఒక్కరోజులో సీతాదేవిని తెచ్చి అప్పజెప్పేవాడినని వాలి పలికాడు.', 3),
     ('ఇంతలో ఒక వేటగాడు క్రూరబాణంతో మగపక్షిని నేలకూల్చాడు.', 0), ('పుష్పకవిమానంలో వెళుతూ ఆయా ప్రదేశాలన్నీ సీతకు చూపుతున్నాడు.', 5)],
    [('మారీచుడి మాటలను రావణుడు పెడచెవిన పెట్టాడు.', 2), ('అంగదుని చేతిలో రావణుని కుమారుడు ఇంద్రజిత్తు ఓడిపోయాడు.', 5),
     ('ఒకనాటి అర్ధరాత్రి మాయావి కిష్కింధకు వచ్చి వాలిని యుద్ధానికి ఆహ్వానించాడు.', 3), ('నిద్ర లేచిన రావణుడు అశోకవనం వైపు అడుగులు వేస్తున్నాడు.', 4)],
    [('లంకేశుడు తన భవనం మీది నుంచే పరిస్థితిని గమనించాడు.', 5), ('హనుమంతుడు మొదలైన వానరులు అణువణువునా గాలిస్తున్నారు.', 3),
     ('జనకుడు సీతారాముల వివాహం జరపడానికి సంసిద్ధుడయ్యాడు.', 0), ('సాయంత్రానికి సీతారామలక్ష్మణులు భరద్వాజ ఆశ్రమానికి చేరారు.', 1)],
    [('భరతుడు శ్రీరాముని పాదుకలకు పట్టాభిషేకం చేశాడు.', 1), ('విభీషణుడు శ్రీరాముడిని శరణాగతి పొందాడు.', 5),
     ('హనుమంతుడు అశోకవనంలో సీతను దర్శించాడు.', 4), ('శ్రీరామ సుగ్రీవులు అగ్నిసాక్షిగా మిత్రులయ్యారు.', 3)],
    [('అంగరంగ వైభవంగా శ్రీరామ పట్టాభిషేక మహోత్సవం జరిగింది.', 5), ('దారిలో అందరూ మధువనంలోకి వెళ్ళారు.', 4),
     ('శ్రీరాముణ్ణి చూడాలనివుంది, వెంటనే తీసుకురమ్మన్నాడు దశరథుడు.', 1), ('ధనుర్బాణాలు ధరించిన వాళ్ళెవరో మారువేషంలో వెళ్ళి కనుక్కోమన్నాడు సుగ్రీవుడు.', 3)],
]
for i, S in enumerate(SETS):
    qs = '\n'.join(f'{L[j]}) {s}' for j, (s, k) in enumerate(S))
    ans = '\n'.join(f'{L[j]}) {s} – {KANDA[k]}' for j, (s, k) in sorted(enumerate(S), key=lambda t: t[1][1]))
    q(1, 8, KQ + qs, 'కాండల క్రమంలో (బాల → అయోధ్య → అరణ్య → కిష్కింధ → సుందర → యుద్ధ):\n' + ans)

ESS = [
 ('రామాయణ ప్రాశస్త్యాన్ని గురించి రాయండి.',
  '• రామాయణం ఆదికావ్యం; దీనిని రచించిన వాల్మీకి ఆదికవి. 24 వేల శ్లోకాలు, ఆరు కాండలు (బాల, అయోధ్య, అరణ్య, కిష్కింధ, సుందర, యుద్ధ) – ఉత్తరకాండ కలిపి ఏడు.\n'
  '• క్రౌంచ పక్షుల జంటలో మగపక్షిని వేటగాడు చంపగా వాల్మీకి శోకం శ్లోకంగా మారింది; బ్రహ్మ ఆశీస్సుతో రామకథను రచించాడు.\n'
  '• రామాయణం మానవ సంబంధాలకు అద్దం: తండ్రి మాట కోసం రాజ్యాన్ని వదిలిన కొడుకు, అన్న వెంట నడిచిన తమ్ముడు, భర్త వెంట అడవికి వెళ్ళిన భార్య, అన్న పాదుకలతో పాలించిన భరతుడు, స్వామిభక్తికి హనుమంతుడు, స్నేహానికి సుగ్రీవుడు.\n'
  '• “రామో విగ్రహవాన్ ధర్మః” – ధర్మానికి రూపమే రాముడు. సత్యం, ధర్మం, త్యాగం, సోదరప్రేమ, స్నేహం వంటి విలువలను నేర్పుతుంది.\n'
  '• భారతీయ భాషలన్నింటిలో అనువాదాలు వచ్చాయి; తెలుగులో రంగనాథ రామాయణం, భాస్కర రామాయణం, మొల్ల రామాయణం, విశ్వనాథ “రామాయణ కల్పవృక్షం” ప్రసిద్ధం.\n'
  '• నాటకాలు, హరికథలు, తోలుబొమ్మలాటలు, సినిమాల ద్వారా తరతరాలుగా ప్రజల జీవితంలో భాగమైంది. అందుకే రామాయణం సర్వకాలాలకూ ఆదర్శ గ్రంథం.'),
 ('సీతారామ కళ్యాణాన్ని రాయండి.',
  '• యాగ సంరక్షణ తర్వాత విశ్వామిత్రుడు రామలక్ష్మణులను మిథిలా నగరానికి తీసుకువెళ్ళాడు. దారిలో గౌతముని ఆశ్రమంలో రాముని పాదస్పర్శతో అహల్యకు శాపవిమోచనం కలిగింది.\n'
  '• మిథిలా రాజు జనకుడు యజ్ఞం కోసం భూమి దున్నుతుండగా నాగటి చాలులో దొరికిన బిడ్డ సీత (అయోనిజ).\n'
  '• జనకుని దగ్గర శివుడి ధనుస్సు (హరధనుస్సు) ఉంది. దానిని ఎక్కుపెట్టినవానికే సీతను ఇస్తానని జనకుడు ప్రతిజ్ఞ చేశాడు; ఎందరో రాజులు కనీసం కదపలేకపోయారు.\n'
  '• విశ్వామిత్రుని ఆజ్ఞతో రాముడు ధనుస్సును అవలీలగా ఎత్తి, నారి కట్టి లాగగా అది మధ్యకు విరిగి పెద్ద శబ్దం చేసింది.\n'
  '• జనకుడు సంతోషించి దశరథునికి కబురు పంపాడు. దశరథుడు సపరివారంగా మిథిలకు వచ్చాడు.\n'
  '• శుభముహూర్తంలో రాముడు సీతను, లక్ష్మణుడు ఊర్మిళను, భరతుడు మాండవిని, శత్రుఘ్నుడు శ్రుతకీర్తిని వివాహమాడారు. “ఇయం సీతా మమ సుతా సహధర్మచరీ తవ” అని జనకుడు సీతను రాముని చేతిలో పెట్టాడు.\n'
  '• తిరుగు దారిలో పరశురాముని గర్వం అణచి, అందరూ అయోధ్యకు చేరుకున్నారు. అయోధ్య ఆనందంలో మునిగిపోయింది.'),
 ('రామాయణం ఆధారంగా విశ్వామిత్రుడు ఉత్తమ గురువు అని నిరూపించండి.',
  '• విశ్వామిత్రుడు తపశ్శక్తితో రాజర్షి నుండి బ్రహ్మర్షి అయిన మహర్షి. యాగ రక్షణ కోసం రాముని పంపమని దశరథుని కోరాడు.\n'
  '• శిష్యుల యోగ్యత గుర్తించాడు: బాలుడైన రాముని శక్తిని తెలిసి ధైర్యంగా వెంట తీసుకువెళ్ళాడు.\n'
  '• ఆకలిదప్పులు, అలసట లేకుండా ఉండే బల, అతిబల మంత్రాలను ఉపదేశించాడు.\n'
  '• దారి పొడవునా ఆయా ప్రదేశాల కథలు, చరిత్రలు (గంగావతరణం, భగీరథ ప్రయత్నం వంటివి) చెప్పి జ్ఞానం పెంచాడు.\n'
  '• తాటక స్త్రీ అని సంకోచించిన రామునికి దుష్టశిక్షణ రాజధర్మమని బోధించి వధింపజేశాడు.\n'
  '• ఎన్నో దివ్యాస్త్రాలను వాటి ఉపసంహార మంత్రాలతో సహా రామునికి ఇచ్చాడు.\n'
  '• యాగ సంరక్షణలో సుబాహుని వధ, మారీచుని దూరంగా విసిరివేత జరిగేలా మార్గదర్శనం చేశాడు.\n'
  '• అహల్య శాపవిమోచనం, సీతాస్వయంవరం, సీతారామ కళ్యాణం జరిపించాడు.\n'
  'ఇలా శిష్యునికి విద్య, ధైర్యం, ధర్మం, జీవితం – అన్నీ అందించిన విశ్వామిత్రుడు ఉత్తమ గురువు.'),
 ('శ్రీరాముడు వనవాసానికి వెళ్ళడానికి గల కారణమేమిటి?',
  '• వృద్ధుడైన దశరథుడు రాముని యువరాజుగా పట్టాభిషేకం చేయాలని నిర్ణయించాడు; అయోధ్య అంతా సంబరాల్లో మునిగింది.\n'
  '• కైక దాసి మంథర ఈ వార్త విని అసూయతో కైక మనసు విరిచింది – రాముడు రాజైతే భరతుడు, నువ్వు దాసులవుతారని నూరిపోసింది.\n'
  '• గతంలో దేవాసుర యుద్ధంలో దశరథుని ప్రాణాలు కాపాడినందుకు ఆయన కైకకు రెండు వరాలు ఇచ్చాడు. ఆ వరాలను ఇప్పుడు అడగమని మంథర సలహా ఇచ్చింది.\n'
  '• కైక అలకగృహం చేరి, 1) భరతునికి పట్టాభిషేకం, 2) రామునికి పద్నాలుగేళ్ళ వనవాసం – అనే రెండు వరాలు కోరింది.\n'
  '• సత్యవ్రతుడైన దశరథుడు మాట తప్పలేక కుప్పకూలాడు; కన్నీళ్ళు తప్ప మాట రాలేదు.\n'
  '• తండ్రి మాట నిలబెట్టడం కోసం రాముడు సంతోషంగా అంగీకరించాడు – “రాజ్యమైనా వనవాసమైనా నాకు సమానమే” అన్నాడు.\n'
  '• సీత, లక్ష్మణుడు రాముని వెంట అడవికి బయలుదేరారు. ఈ విధంగా మంథర దుర్బోధ, కైక వరాలు, దశరథుని సత్యనిష్ఠ, రాముని పితృవాక్య పరిపాలనే వనవాసానికి కారణాలు.'),
 ('సీతాపహరణం గురించి రాయండి.',
  '• పంచవటిలో రావణుని చెల్లెలు శూర్పణఖ రాముని, లక్ష్మణుని పెళ్ళాడమని వేధించి సీతపై దాడికి దిగగా లక్ష్మణుడు ఆమె ముక్కు చెవులు కోశాడు.\n'
  '• ఖరదూషణాదులు పద్నాలుగు వేల రాక్షసులతో వచ్చి రాముని చేతిలో హతమయ్యారు.\n'
  '• శూర్పణఖ రావణుని దగ్గరకు వెళ్ళి సీత అందాన్ని పొగిడి, ఆమెను అపహరించమని రెచ్చగొట్టింది (అగ్నికి ఆజ్యం పోసినట్లు).\n'
  '• రావణుడు మారీచుని సహాయం కోరాడు. మారీచుడు రాముని పరాక్రమం చెప్పి హెచ్చరించినా రావణుడు పెడచెవిన పెట్టి బెదిరించాడు.\n'
  '• మారీచుడు బంగారు లేడిగా మారి పంచవటిలో తిరిగాడు. సీత దానిని కోరగా రాముడు వెంబడించి బాణం వేశాడు. చనిపోతూ మారీచుడు “హా సీతా! హా లక్ష్మణా!” అని రాముని గొంతుతో అరిచాడు.\n'
  '• సీత బలవంతం చేయడంతో లక్ష్మణుడు రాముని దగ్గరకు వెళ్ళాడు.\n'
  '• ఒంటరిగా ఉన్న సీత దగ్గరకు రావణుడు సన్యాసి వేషంలో వచ్చి, తర్వాత నిజరూపం చూపి బలవంతంగా రథంలో ఎక్కించుకొని ఆకాశమార్గాన లంకకు బయలుదేరాడు.\n'
  '• జటాయువు రావణుని ఎదిరించి పోరాడి, రెక్కలు తెగి నేలకూలాడు. సీత తన ఆభరణాలను ఒక మూటగా కట్టి ఋష్యమూకం మీది వానరుల మధ్య జారవిడిచింది.\n'
  '• రావణుడు సీతను లంకలోని అశోకవనంలో రాక్షస స్త్రీల కాపలాలో ఉంచాడు.'),
 ('శ్రీరామ సుగ్రీవుల మైత్రి ఎలా ఏర్పడింది?',
  '• సీతను వెతుకుతూ రామలక్ష్మణులు కబంధుని సలహాతో, శబరి ఆతిథ్యం స్వీకరించి పంపా సరస్సు దగ్గరి ఋష్యమూక పర్వతానికి చేరారు.\n'
  '• ధనుర్బాణాలు ధరించిన వారెవరో మారువేషంలో వెళ్ళి కనుక్కోమని సుగ్రీవుడు హనుమంతుని పంపాడు.\n'
  '• హనుమంతుడు బ్రాహ్మణ వేషంలో వచ్చి వినయంగా మాట్లాడాడు; అతని వాక్చాతుర్యాన్ని రాముడు మెచ్చుకున్నాడు.\n'
  '• హనుమంతుడు రామలక్ష్మణులను భుజాలపై ఎక్కించుకొని సుగ్రీవుని దగ్గరకు తీసుకువెళ్ళాడు.\n'
  '• అగ్నిని రగిలించి, అగ్నిసాక్షిగా శ్రీరామ సుగ్రీవులు మిత్రులయ్యారు.\n'
  '• సుగ్రీవుడు సీత జారవిడిచిన ఆభరణాలను చూపాడు; వాలితో వైరం ఎందుకు వచ్చిందో రాముడు అడగగా సుగ్రీవుడు మాయావి వృత్తాంతం, అన్న తనను వెళ్ళగొట్టి భార్యను హరించిన విషయం చెప్పాడు.\n'
  '• వాలిని చంపి కిష్కింధ రాజ్యం ఇప్పిస్తానని రాముడు, సీతను వెతికి తెచ్చేందుకు సహాయం చేస్తానని సుగ్రీవుడు ప్రతిజ్ఞ చేశారు.\n'
  '• రాముడు వాలిని సంహరించి సుగ్రీవునికి పట్టాభిషేకం చేశాడు. ఈ మైత్రి నిజమైన స్నేహానికి ఆదర్శం.'),
 ('సీతాన్వేషణ వృత్తాంతం రాయండి.',
  '• వర్షాకాలం గడిచాక సుగ్రీవుడు నాలుగు దిక్కులకు వానర సేనలను పంపి, నెలరోజుల్లో సీత జాడ తెలియకపోతే మరణదండన అని సుగ్రీవాజ్ఞ ఇచ్చాడు.\n'
  '• దక్షిణ దిక్కుకు అంగదుని నాయకత్వంలో హనుమంతుడు, జాంబవంతుడు మొదలైనవారు వెళ్ళారు. రాముడు గుర్తుగా తన ఉంగరాన్ని హనుమంతునికి ఇచ్చాడు.\n'
  '• వానరులు అణువణువునా గాలించారు; స్వయంప్రభ గుహలో దారి తప్పి బయటపడ్డారు. గడువు దాటిపోవడంతో ప్రాయోపవేశానికి సిద్ధపడ్డారు.\n'
  '• జటాయువు అన్న సంపాతి సీత లంకలో ఉందని తెలిపాడు.\n'
  '• జాంబవంతుడు హనుమంతునికి అతని శక్తిని గుర్తుచేశాడు. హనుమంతుడు మహేంద్ర పర్వతం నుండి సముద్రాన్ని లంఘించాడు; దారిలో మైనాకుని ఆతిథ్యం, సురస పరీక్ష, సింహిక సంహారం దాటి లంక చేరాడు.\n'
  '• రాత్రివేళ లంకిణిని జయించి, నగరమంతా వెతికి చివరకు అశోకవనంలో శింశుపా వృక్షం కింద శోకిస్తున్న సీతను దర్శించాడు.\n'
  '• రామకథ వినిపించి, తాను శ్రీరామదూతనని చెప్పి ఉంగరం ఇచ్చాడు. సీత గుర్తుగా చూడామణి ఇచ్చింది.\n'
  '• తిరిగి వచ్చి “చూశాను సీతను” అని రామునికి శుభవార్త చెప్పాడు.'),
 ('లంకాదహనం వర్ణించండి.',
  '• సీతను దర్శించిన తర్వాత రావణుని బలం తెలుసుకోవాలని హనుమంతుడు అశోకవనాన్ని ధ్వంసం చేశాడు.\n'
  '• తనను పట్టడానికి వచ్చిన కింకరులను, జంబుమాలిని, మంత్రి కుమారులను, రావణుని కుమారుడు అక్షకుమారుని సంహరించాడు.\n'
  '• ఇంద్రజిత్తు బ్రహ్మాస్త్రం ప్రయోగించగా దానిని గౌరవించి కట్టుబడినట్లు నటించి రావణుని సభకు చేరాడు.\n'
  '• రాముని గొప్పతనం చెప్పి సీతను తిరిగి అప్పగించమని హితవు పలికాడు. రావణుడు కోపంతో చంపమన్నాడు; దూతను చంపడం తగదని విభీషణుడు అడ్డుచెప్పాడు.\n'
  '• కోతులకు తోక అంటే ఇష్టం కనుక దానికి నిప్పంటించమని రావణుడు ఆజ్ఞాపించాడు. రాక్షసులు తోకకు గుడ్డలు చుట్టి నూనె పోసి నిప్పంటించి ఊరేగించారు.\n'
  '• సీత ప్రార్థనతో అగ్ని హనుమంతుణ్ణి చల్లగా తాకింది. హనుమంతుడు బంధాలు తెంచుకొని మేడల మీదకు ఎగిరి, మండుతున్న తోకతో లంకలోని భవనాలన్నిటికీ నిప్పంటించాడు; ఒక్క విభీషణుని ఇల్లు తప్ప లంక అంతా తగలబడింది.\n'
  '• సముద్రంలో తోకను చల్లార్చుకొని, సీత క్షేమంగా ఉందని నిర్ధారించుకొని తిరిగి ప్రయాణమయ్యాడు.'),
 ('సేతువు నిర్మాణం గురించి రాయండి.',
  '• హనుమంతుడు తెచ్చిన వార్తతో రాముడు వానర సేనతో దక్షిణ సముద్ర తీరానికి చేరాడు. విభీషణుడు వచ్చి శరణాగతి పొందాడు.\n'
  '• సముద్రాన్ని దాటే మార్గం కోసం రాముడు మూడు రోజులు సముద్రుని ప్రార్థించాడు. సముద్రుడు రాకపోవడంతో కోపించి బాణం ఎక్కుపెట్టాడు.\n'
  '• భయపడిన సముద్రుడు ప్రత్యక్షమై, విశ్వకర్మ కుమారుడైన నలుడు వారధి కట్టగలడని, తాను దానిని నిలుపుతానని చెప్పాడు.\n'
  '• నలుని నాయకత్వంలో వానరులు పెద్ద పెద్ద చెట్లు, బండరాళ్ళు, కొండలు తెచ్చి సముద్రంలో వేశారు.\n'
  '• ఐదు రోజుల్లో నూరు యోజనాల పొడవు, పది యోజనాల వెడల్పు గల సేతువు పూర్తయింది. దేవతలు, ఋషులు ఆశ్చర్యపోయారు.\n'
  '• (జానపద గాథ ప్రకారం ఉడుత కూడా ఇసుక తెచ్చి సాయం చేసి రాముని ప్రేమ పొందింది.)\n'
  '• ఆ వారధి మీదుగా వానర సేన లంకకు చేరింది. ఇది సమష్టి కృషికి, పట్టుదలకు నిదర్శనం.'),
 ('రామరావణ యుద్ధాన్ని గురించి రాయండి.',
  '• యుద్ధానికి ముందు రాముడు అంగదుని దూతగా పంపి సీతను అప్పగించమని చెప్పించాడు; రావణుడు ఒప్పుకోలేదు.\n'
  '• భయంకరమైన యుద్ధం మొదలైంది. ఇంద్రజిత్తు నాగపాశంతో రామలక్ష్మణులను బంధించగా గరుత్మంతుడు వచ్చి విడిపించాడు.\n'
  '• కుంభకర్ణుడు నిద్ర లేచి వానర సేనను చీల్చిచెండాడగా రాముడు అతణ్ణి సంహరించాడు.\n'
  '• ఇంద్రజిత్తు ప్రయోగించిన శక్తికి లక్ష్మణుడు మూర్ఛపోగా హనుమంతుడు సంజీవని పర్వతాన్ని తెచ్చి ప్రాణం పోశాడు. లక్ష్మణుడు ఇంద్రజిత్తును సంహరించాడు.\n'
  '• చివరకు రావణుడు స్వయంగా యుద్ధానికి వచ్చాడు. ఇంద్రుడు మాతలి సారథిగా తన రథాన్ని రామునికి పంపాడు. అగస్త్యుడు ఆదిత్య హృదయం ఉపదేశించాడు.\n'
  '• రాముడు రావణుని తలలు నరికినా మళ్ళీ మళ్ళీ మొలిచాయి. మాతలి సూచనతో బ్రహ్మాస్త్రాన్ని ప్రయోగించి రావణుని గుండెను చీల్చి సంహరించాడు.\n'
  '• విభీషణునికి లంకా పట్టాభిషేకం జరిగింది; విభీషణుడు పల్లకీలో సీతను రాముని దగ్గరకు చేర్చాడు. ధర్మం గెలిచింది, అధర్మం ఓడింది.'),
 ('రామాయణం ఆధారంగా శ్రీరాముని ఉత్తమ వ్యక్తిత్వాన్ని విశ్లేషించండి.',
  '• పితృవాక్య పరిపాలకుడు: తండ్రి మాట కోసం రాజ్యాన్ని తృణప్రాయంగా వదిలి వనవాసం చేశాడు – “రాజ్యమైనా వనవాసమైనా సమానమే”.\n'
  '• ధర్మమూర్తి: “రామో విగ్రహవాన్ ధర్మః”. ఎన్ని కష్టాలు వచ్చినా ధర్మం తప్పలేదు.\n'
  '• ఏకపత్నీవ్రతుడు, సత్యవాక్పరిపాలకుడు: “రాముడు రెండు మాటలాడడు”.\n'
  '• స్నేహశీలి: గుహుడు, సుగ్రీవుడు, విభీషణుడు వంటి వారితో కులం, జాతి చూడకుండా స్నేహం చేశాడు; శబరి ఎంగిలి పండ్లను ప్రేమతో స్వీకరించాడు.\n'
  '• శరణాగత రక్షకుడు: శత్రువు తమ్ముడైన విభీషణుని కూడా శరణు ఇచ్చి కాపాడాడు.\n'
  '• వీరుడు: తాటక, సుబాహు, ఖరదూషణాదులు, వాలి, కుంభకర్ణ, రావణులను సంహరించి దుష్టశిక్షణ చేశాడు.\n'
  '• సోదర ప్రేమ, వినయం, ఓర్పు, కృతజ్ఞత కలవాడు; ఉత్తమ పాలకుడు – “రామరాజ్యం” నేటికీ ఆదర్శం.\n'
  'అందుకే శ్రీరాముడు మర్యాదా పురుషోత్తముడు – మానవాళికి ఆదర్శ పురుషుడు.'),
 ('రామాయణంలోని మానవ సంబంధాల గురించి రాయండి.',
  '• తండ్రీకొడుకులు: తండ్రి మాట కోసం రాముడు వనవాసం చేశాడు; కొడుకు వియోగాన్ని తట్టుకోలేక దశరథుడు ప్రాణాలు విడిచాడు.\n'
  '• అన్నదమ్ములు: లక్ష్మణుడు అన్న వెంట అడవికి వెళ్ళి సేవ చేశాడు; భరతుడు రాజ్యాన్ని తిరస్కరించి రాముని పాదుకలకు పట్టాభిషేకం చేసి నందిగ్రామంలో ఉండి పాలించాడు. (దీనికి విరుద్ధంగా వాలి–సుగ్రీవుల వైరం, రావణ–విభీషణుల విభేదం.)\n'
  '• భార్యాభర్తలు: సీత సుఖాలు వదిలి భర్త వెంట అడవికి నడిచింది; రాముడు ఏకపత్నీవ్రతుడు.\n'
  '• తల్లీబిడ్డలు: కౌసల్య, సుమిత్ర ప్రేమ; సుమిత్ర “రాముని దశరథునిగా, సీతను నన్నుగా, అడవిని అయోధ్యగా భావించు” అని లక్ష్మణుని పంపింది.\n'
  '• గురుశిష్యులు: విశ్వామిత్ర–రాముల బంధం.\n'
  '• స్నేహం: రామ–సుగ్రీవ, రామ–గుహ, రామ–విభీషణ మైత్రి.\n'
  '• స్వామిభక్తి: హనుమంతుని సేవ; జటాయువు త్యాగం.\n'
  'ఈ విధంగా రామాయణం కుటుంబ, సామాజిక సంబంధాలకు ఆదర్శ గ్రంథం.'),
]
for i, (qq, a) in enumerate(ESS):
    q(1, 8, qq, a)

CH = [
 ('విశ్వామిత్రుడు', 'గాధిరాజు కుమారుడు; రాజుగా ఉండి కఠోర తపస్సుతో బ్రహ్మర్షి అయ్యాడు. యాగ సంరక్షణకు రామలక్ష్మణులను తీసుకువెళ్ళి బల, అతిబల మంత్రాలు, దివ్యాస్త్రాలు ఇచ్చాడు. తాటక వధ, అహల్య శాపవిమోచనం, సీతారామ కళ్యాణం జరిపించిన ఉత్తమ గురువు. పట్టుదల, తపశ్శక్తికి ప్రతీక.'),
 ('మారీచుడు', 'తాటక కుమారుడు, రాక్షసుడు. యాగ సమయంలో రాముని బాణానికి సముద్రంలో పడి, రాముని శక్తి తెలుసుకున్నాడు. సీతను అపహరించవద్దని రావణునికి హితవు చెప్పాడు; అయినా రావణుని బెదిరింపుకు లొంగి బంగారు లేడిగా మారాడు. రాముని బాణానికి చనిపోతూ “హా సీతా! హా లక్ష్మణా!” అని అరిచి మోసం చేశాడు. మాయావి, భయస్తుడు.'),
 ('హనుమంతుడు', 'అంజనీ, వాయుదేవుల కుమారుడు; సుగ్రీవుని మంత్రి. బలం, బుద్ధి, వాక్చాతుర్యం, వినయం కలవాడు. సముద్రాన్ని లంఘించి సీతను దర్శించాడు, లంకాదహనం చేశాడు, సంజీవని తెచ్చి లక్ష్మణుని కాపాడాడు. రామభక్తికి, స్వామిభక్తికి, కార్యదక్షతకు ఆదర్శం – “రామదూత”.'),
 ('మంథర', 'కైక దాసి, గూనిది. రాముని పట్టాభిషేకం విని అసూయ పడింది. కైక మనసు విరిచి, దశరథుడు ఇచ్చిన రెండు వరాలు అడగమని దుర్బోధ చేసింది. స్వార్థం, అసూయ, కుటిలత్వానికి ప్రతీక; రామాయణంలో వనవాసానికి మూలకారణమైన పాత్ర.'),
 ('కైక', 'దశరథుని మూడో భార్య, భరతుని తల్లి. దేవాసుర యుద్ధంలో దశరథుని ప్రాణాలు కాపాడిన వీరనారి. మొదట రాముని ప్రేమించినా మంథర దుర్బోధకు లొంగి భరతునికి పట్టాభిషేకం, రామునికి 14 ఏళ్ళ వనవాసం అనే వరాలు కోరింది. దశరథుని మరణానికి, భరతుని ఆగ్రహానికి గురైంది. చెప్పుడు మాటలు వింటే కలిగే అనర్థానికి ఉదాహరణ.'),
 ('భరతుడు', 'దశరథ కైకల కుమారుడు. తల్లి కోరిన రాజ్యాన్ని తిరస్కరించి, అడవికి వెళ్ళి రాముని తిరిగి రమ్మని ప్రార్థించాడు. రాముని పాదుకలు తెచ్చి సింహాసనంపై ఉంచి పట్టాభిషేకం చేసి, నందిగ్రామంలో నారచీరలు ధరించి రాముని ప్రతినిధిగా పాలించాడు. త్యాగానికి, సోదర ప్రేమకు నిలువెత్తు రూపం.'),
 ('సుగ్రీవుడు', 'వాలి తమ్ముడు, వానర రాజు. అన్న వాలి వెళ్ళగొట్టగా ఋష్యమూకంపై తలదాచుకున్నాడు. అగ్నిసాక్షిగా రామునితో మైత్రి చేశాడు. రాముని సాయంతో రాజ్యం పొంది, కొంత ఆలస్యం చేసినా లక్ష్మణుని హెచ్చరికతో నాలుగు దిక్కులకు వానరులను పంపి సీతాన్వేషణ చేయించాడు; యుద్ధంలో రామునికి అండగా నిలిచాడు. కృతజ్ఞత గల మిత్రుడు.'),
 ('వాలి', 'కిష్కింధ రాజు, ఇంద్రుని కుమారుడు, మహా బలశాలి – ఎదురుగా పోరాడేవారి బలంలో సగం పొందే వరం కలవాడు. మాయావితో యుద్ధం సందర్భంగా తమ్ముడు సుగ్రీవుని అపార్థం చేసుకొని వెళ్ళగొట్టి అతని భార్యను హరించాడు. తార హెచ్చరికను పట్టించుకోలేదు. రాముని బాణానికి నేలకూలి, చనిపోయే ముందు తప్పు తెలుసుకొని అంగదుని సుగ్రీవునికి అప్పగించాడు. బలం ఉన్నా అహంకారం పతనానికి దారి తీస్తుందని తెలిపే పాత్ర.'),
 ('సీత', 'జనకుని కుమార్తె (అయోనిజ), రాముని ధర్మపత్ని. సుఖాలు వదిలి భర్త వెంట అడవికి వెళ్ళింది. రావణుని చెరలో ఉన్నా అతని బెదిరింపులకు లొంగక పాతివ్రత్యాన్ని కాపాడుకుంది. ఓర్పు, ధైర్యం, శీలం, పతిభక్తికి ఆదర్శం – భారత స్త్రీత్వానికి ప్రతీక.'),
 ('ఇంద్రజిత్తు', 'రావణుని కుమారుడు మేఘనాథుడు; ఇంద్రుని జయించినందున ఇంద్రజిత్తు అనే పేరు. మాయా యుద్ధంలో నేర్పరి – నాగపాశంతో రామలక్ష్మణులను బంధించాడు; బ్రహ్మాస్త్రంతో హనుమంతుని కట్టాడు; శక్తితో లక్ష్మణుని మూర్ఛపోయేలా చేశాడు. తండ్రి కోసం ప్రాణాలకు తెగించిన వీరుడు; చివరకు లక్ష్మణుని చేతిలో మరణించాడు.'),
 ('రావణుడు', 'లంకాధిపతి, పది తలలవాడు. గొప్ప శివభక్తుడు, వీణా విద్వాంసుడు, పండితుడు, వీరుడు. కానీ కామం, అహంకారంతో సీతను అపహరించాడు. మారీచుడు, విభీషణుడు, హనుమంతుడు హితం చెప్పినా వినలేదు. తన వంశాన్నంతా నాశనం చేసుకొని రాముని బ్రహ్మాస్త్రానికి మరణించాడు. ఎంత గొప్పవాడైనా దుర్గుణాలు పతనానికి దారి తీస్తాయని తెలిపే పాత్ర.'),
 ('దశరథుడు', 'అయోధ్య రాజు, ఇక్ష్వాకు వంశం; కౌసల్య, సుమిత్ర, కైక భార్యలు. పుత్రకామేష్టి యాగంతో నలుగురు కుమారులను పొందాడు. సత్యవ్రతుడు – కైకకు ఇచ్చిన మాట తప్పలేక రాముని అడవికి పంపి, పుత్రవియోగంతో ప్రాణాలు విడిచాడు. పుత్రప్రేమకు, సత్యనిష్ఠకు ప్రతీక.'),
 ('లక్ష్మణుడు', 'దశరథ సుమిత్రల కుమారుడు. అన్న రాముని నీడలా అనుసరించి 14 ఏళ్ళు నిద్రాహారాలు మాని సేవ చేశాడు. శూర్పణఖను శిక్షించాడు; సుగ్రీవుని హెచ్చరించాడు; ఇంద్రజిత్తును సంహరించాడు. కోపం ఎక్కువైనా అన్నపై అపార భక్తి, సోదర ప్రేమకు ఆదర్శం.'),
 ('రాముడు', 'దశరథ కౌసల్యల జ్యేష్ఠ పుత్రుడు. పితృవాక్య పరిపాలకుడు, ధర్మమూర్తి, ఏకపత్నీవ్రతుడు, సత్యవాక్కు గలవాడు. శరణాగత రక్షకుడు – విభీషణునికీ శరణిచ్చాడు. గుహ, సుగ్రీవ, శబరి వంటి వారిని ఆదరించాడు. దుష్టశిక్షణ, శిష్టరక్షణ చేసిన మర్యాదా పురుషోత్తముడు; “రామరాజ్యం” ఉత్తమ పాలనకు ఆదర్శం.'),
 ('త్రిజట', 'వృద్ధ రాక్షస స్త్రీ (కొన్ని గాథల్లో విభీషణుని కూతురు); అశోకవనంలో సీతకు కాపలా ఉన్నవారిలో ఒకరు. ఇతర రాక్షస స్త్రీలు సీతను బెదిరిస్తుంటే వారిని వారించింది. రాక్షస వంశ నాశనం, రాముని విజయం కలలో చూశానని చెప్పి సీతకు ధైర్యం, ఓదార్పు ఇచ్చింది. రాక్షస కులంలో పుట్టినా మంచితనం, దయ గల పాత్ర.'),
]
for n, a in CH:
    q(1, 4, f'పాత్ర స్వభావం రాయండి: {n}', a)

JT = [
 ('చెవిటివాని చెవిలో శంఖం ఊదినట్లు', 'అర్థం: ఎంత మంచి మాట చెప్పినా వినిపించుకోకపోవడం – చెప్పడం వృథా.\nసందర్భం: సీతను అప్పగించమని మారీచుడు, విభీషణుడు, హనుమంతుడు చెప్పిన హితవు రావణునికి చెవిటివాని చెవిలో శంఖం ఊదినట్లయింది.'),
 ('చెవినిల్లు కట్టుకొని పోరు', 'అర్థం: ఒకే విషయాన్ని మళ్ళీ మళ్ళీ చెప్పి ఒత్తిడి చేయడం.\nసందర్భం: మంథర కైక చెవినిల్లు కట్టుకొని పోరి ఆమె మనసు మార్చింది.'),
 ('గతజల సేతుబంధనం', 'అర్థం: నీళ్ళు పోయాక ఆనకట్ట కట్టినట్లు – జరగవలసింది జరిగిపోయాక చర్య తీసుకోవడం వృథా.\nసందర్భం: రావణుడు వంశమంతా నశించాక పశ్చాత్తాపపడడం గతజల సేతుబంధనమే.'),
 ('అగస్త్య భ్రాత', 'అర్థం: సొంత పేరు, గుర్తింపు లేక ఇతరుల సంబంధంతోనే పిలవబడేవాడు (అగస్త్యుని తమ్ముడి పేరు ఎవరికీ తెలియదు).\nసందర్భం: సీతారామలక్ష్మణులు అరణ్యవాసంలో అగస్త్య భ్రాత ఆశ్రమాన్ని దర్శించారు. ఉదా: పెద్దవారి నీడలో ఉండి సొంత గుర్తింపు లేనివాడు “అగస్త్య భ్రాత”.'),
 ('సుగ్రీవాజ్ఞ', 'అర్థం: తప్పనిసరిగా పాటించవలసిన కఠినమైన, తిరుగులేని ఆజ్ఞ.\nసందర్భం: నెలరోజుల్లో సీత జాడ తెలియకపోతే మరణదండన అని సుగ్రీవుడు వానరులకు ఆజ్ఞ ఇచ్చాడు.'),
 ('శ్రీరామరక్ష', 'అర్థం: తిరుగులేని, సంపూర్ణ రక్షణ.\nసందర్భం: శరణు కోరిన విభీషణునికి రాముడు ఇచ్చిన అభయం శ్రీరామరక్ష. ఉదా: తల్లిదండ్రుల ఆశీస్సులే పిల్లలకు శ్రీరామరక్ష.'),
 ('కబంధహస్తాలు', 'అర్థం: తప్పించుకోలేని పట్టు, బంధనం (కబంధుని పొడవైన చేతులు).\nసందర్భం: సీతను వెతుకుతున్న రామలక్ష్మణులు కబంధుని హస్తాల్లో చిక్కారు. ఉదా: పేదలు వడ్డీ వ్యాపారుల కబంధహస్తాల్లో చిక్కారు.'),
 ('భగీరథ ప్రయత్నం', 'అర్థం: ఎంతో కష్టమైన పనిని పట్టుదలతో చేసే గొప్ప ప్రయత్నం.\nసందర్భం: భగీరథుడు తపస్సు చేసి గంగను భూమికి తెచ్చిన కథను విశ్వామిత్రుడు రామునికి చెప్పాడు (బాలకాండ).'),
 ('బూడిదలో పోసిన పన్నీరు', 'అర్థం: చేసిన మంచి పని / ప్రయత్నం వృథా కావడం.\nసందర్భం: రావణునికి విభీషణుడు చెప్పిన హితవు బూడిదలో పోసిన పన్నీరైంది.'),
 ('గుండెల్లో రాయిపడటం', 'అర్థం: ఊహించని వార్తతో తీవ్రమైన భయం, ఆందోళన కలగడం.\nసందర్భం: కైక కోరిన వరాలు విని దశరథుని గుండెల్లో రాయి పడింది.'),
 ('అగ్నికి ఆజ్యం పోయడం', 'అర్థం: ఉన్న కోపాన్ని / సమస్యను మరింత పెంచడం.\nసందర్భం: శూర్పణఖ సీత అందాన్ని వర్ణించి రావణుని కోపానికి, కోరికకు అగ్నికి ఆజ్యం పోసినట్లు చేసింది.'),
 ('పిడుగుపాటు', 'అర్థం: ఊహించని ఆపద, దుర్వార్త.\nసందర్భం: రాముని వనవాస వార్త అయోధ్య ప్రజలకు పిడుగుపాటులా తగిలింది.'),
]
for n, a in JT:
    q(1, 2, f'జాతీయానికి అర్థం, సందర్భం వివరించండి: “{n}”', a)
ITEMS = B.items
